1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function contains(cells: Cell[], cell: Cell): boolean {
8	  return cells.some((candidate) => isSameCell(candidate, cell));
9	}
10	
11	const CELL_DELTAS = [-1, 0, 1];
12	
13	function neighborsOf(cell: Cell): Cell[] {
14	  const [x, y] = cell;
15	  return CELL_DELTAS.flatMap((dx) =>
16	    CELL_DELTAS.map((dy): Cell => [x + dx, y + dy]),
17	  ).filter((neighbor) => !isSameCell(neighbor, cell));
18	}
19	
20	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
21	  return neighborsOf(cell).filter((neighbor) => contains(liveCells, neighbor))
22	    .length;
23	}
24	
25	function survives(cell: Cell, liveCells: Cell[]): boolean {
26	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
27	  return liveNeighbors === 2 || liveNeighbors === 3;
28	}
29	
30	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
31	  return countLiveNeighbors(cell, liveCells) === 3;
32	}
33	
34	function deduplicate(cells: Cell[]): Cell[] {
35	  return cells.filter((cell, index) => !contains(cells.slice(0, index), cell));
36	}
37	
38	function deadNeighborsOf(liveCells: Cell[]): Cell[] {
39	  const allNeighbors = liveCells.flatMap(neighborsOf);
40	  return deduplicate(allNeighbors).filter(
41	    (neighbor) => !contains(liveCells, neighbor),
42	  );
43	}
44	
45	export function nextGeneration(liveCells: Cell[]): Cell[] {
46	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
47	  const births = deadNeighborsOf(liveCells).filter((cell) =>
48	    isBorn(cell, liveCells),
49	  );
50	  return [...survivors, ...births];
51	}
